            for z in range(D):
                if not (x in (0, W-1) or z in (0, D-1)): continue
                corner = x in (0, W-1) and z in (0, D-1)
                horiz = z in (0, D-1)
                run, L = (x, W) if horiz else (z, D)
                s = min(run, L-1-run)
                win = (not corner) and s >= 2 and s % 2 == 0
                fy = y % 4
                name = 'minecraft:sandstone'
                if y < 4: name = 'minecraft:stone' if y % 2 == 0 else 'minecraft:andesite'
                if corner: name = 'minecraft:calcite' if (y // 2) % 2 == 0 else 'minecraft:stone'
                elif win and fy in (1, 2): name = 'minecraft:glass' if y < 4 else 'minecraft:white_stained_glass'
                if z == 0 and x == W // 2 and y in (1, 2): name = 'minecraft:dark_oak_planks'
                put(x, y, z, name)
                if corner: continue
                ox, oz = (x, -1) if z == 0 else ((x, D) if z == D-1 else ((-1, z) if x == 0 else (W, z)))
                if win and fy == 0 and y >= 4: put(ox, y, oz, 'minecraft:sandstone_slab')
                if win and fy == 3: put(ox, y, oz, 'minecraft:stone_brick_wall')
    for k in range(1, F + 1):
        yk = 4 * k
        for x in range(-1, W + 1):
            for z in range(-1, D + 1):
                edge = x in (-1, W) or z in (-1, D)
                if edge: put(x, yk, z, 'minecraft:stone_slab' if k == F else 'minecraft:sandstone_slab')
                elif k == F: put(x, yk, z, 'minecraft:terracotta')
    for x in range(W):
        for z in range(D):
            if (x in (0, W-1) or z in (0, D-1)) and (x + z) % 2 == 0:
